CREATE TABLE "ConceptProgress" ("conceptId" TEXT NOT NULL PRIMARY KEY, "notes" TEXT NOT NULL DEFAULT '', "read" BOOLEAN NOT NULL DEFAULT false, "practice" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "PracticeAttempt" ("id" TEXT NOT NULL PRIMARY KEY, "conceptId" TEXT NOT NULL, "choice" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ReviewCard" ("cardId" TEXT NOT NULL PRIMARY KEY, "dueAt" DATETIME NOT NULL);
CREATE TABLE "ReviewEvent" ("id" TEXT NOT NULL PRIMARY KEY, "cardId" TEXT NOT NULL, "outcome" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "MigrationMarker" ("id" TEXT NOT NULL PRIMARY KEY, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
